perl -e '
use strict;
use warnings;
use File::Find;

my @entities = qw(
    Attachment Memo MemoRelation InstanceSetting User UserSetting
    IdentityProvider Inbox Reaction MemoShare UserIdentity
    AuthenticationConfigState AuthenticationConfigMutation
);

my %related = (
    Attachment => [qw(FindAttachment UpdateAttachment DeleteAttachment)],
    Memo => [qw(FindMemo FindMemoPayload UpdateMemo DeleteMemo)],
    MemoRelation => [qw(FindMemoRelation DeleteMemoRelation)],
    InstanceSetting => [qw(FindInstanceSetting DeleteInstanceSetting)],
    User => [qw(FindUser UpdateUser DeleteUser DeleteUserResult)],
    UserSetting => [qw(FindUserSetting DeleteUserSetting)],
    IdentityProvider => [qw(FindIdentityProvider UpdateIdentityProvider DeleteIdentityProvider UpdateIdentityProviderV1)],
    Inbox => [qw(FindInbox UpdateInbox DeleteInbox)],
    Reaction => [qw(FindReaction DeleteReaction)],
    MemoShare => [qw(FindMemoShare DeleteMemoShare)],
    UserIdentity => [qw(FindUserIdentity DeleteUserIdentity)],
);

my @files;
File::Find::find({
    wanted => sub {
        return unless /\.go$/;
        my $path = $File::Find::name;
        return if $path =~ m{/\.git/};
        return if $path =~ m{/store(?:/|$)};
        push @files, $path;
    },
    no_chdir => 1,
}, "/bench/repo");

print "Go files outside store/: " . scalar(@files) . "\n";

my %entity_pkgs;
my %storepb_pkgs;
my %related_pkgs;
my %entity_hits;

for my $path (@files) {
    open my $fh, "<", $path or die $path;
    my $text = do { local $/; <$fh> };
    close $fh;
    my $pkg = $path;
    $pkg =~ s{/[^/]+$}{};
    for my $ent (@entities) {
        if ($text =~ /\bstore\.\Q$ent\E\b/) {
            $entity_pkgs{$ent}{$pkg} = 1;
            my $n = 0;
            for my $line (split /\n/, $text) {
                $n++;
                if ($line =~ /\bstore\.\Q$ent\E\b/) {
                    push @{$entity_hits{$ent}}, sprintf("%s:%d: %s", $path, $n, substr($line, 0, 120));
                }
            }
        }
        if ($text =~ /\bstorepb\.\Q$ent\E\b/) {
            $storepb_pkgs{$ent}{$pkg} = 1;
        }
        if (my $rels = $related{$ent}) {
            for my $rel (@$rels) {
                if ($text =~ /\bstore\.\Q$rel\E\b/) {
                    $related_pkgs{$ent}{$pkg} = 1;
                }
            }
        }
    }
}

print "\n======= store.Entity references (packages) =======\n";
for my $ent (sort { keys(%{$entity_pkgs{$b}||{}}) <=> keys(%{$entity_pkgs{$a}||{}}) || $a cmp $b } @entities) {
    my @pkgs = sort keys %{$entity_pkgs{$ent}||{}};
    print "$ent: " . scalar(@pkgs) . " packages\n";
    print "  - $_\n" for map { s{^/bench/repo/}{}; $_ } @pkgs;
}

print "\n======= storepb.Entity references (packages) =======\n";
for my $ent (sort { keys(%{$storepb_pkgs{$b}||{}}) <=> keys(%{$storepb_pkgs{$a}||{}}) || $a cmp $b } @entities) {
    my @pkgs = sort keys %{$storepb_pkgs{$ent}||{}};
    next unless @pkgs;
    print "$ent: " . scalar(@pkgs) . " packages\n";
    print "  - $_\n" for map { s{^/bench/repo/}{}; $_ } @pkgs;
}

print "\n======= UNION store.Entity + related =======\n";
for my $ent (@entities) {
    my %u = %{ $entity_pkgs{$ent}||{} };
    $u{$_} = 1 for keys %{ $related_pkgs{$ent}||{} };
    my $ec = keys %{ $entity_pkgs{$ent}||{} };
    my $rc = keys %{ $related_pkgs{$ent}||{} };
    my $uc = keys %u;
    print "$ent: entity=$ec related=$rc union=$uc\n";
    my @extra = grep { !exists $entity_pkgs{$ent}{$_} } keys %{ $related_pkgs{$ent}||{} };
    if (@extra) {
        print "  related-only: " . join(", ", map { s{^/bench/repo/}{}; $_ } sort @extra) . "\n";
    }
}

print "\n======= UNION store.Entity + storepb.Entity =======\n";
for my $ent (sort { 
    my $ua = keys(%{$entity_pkgs{$a}||{}}) + 0; $ua += 0; 
    my %A = %{ $entity_pkgs{$a}||{} }; $A{$_}=1 for keys %{ $storepb_pkgs{$a}||{} };
    my %B = %{ $entity_pkgs{$b}||{} }; $B{$_}=1 for keys %{ $storepb_pkgs{$b}||{} };
    (keys %B) <=> (keys %A) || $a cmp $b
} @entities) {
    my %u = %{ $entity_pkgs{$ent}||{} };
    $u{$_} = 1 for keys %{ $storepb_pkgs{$ent}||{} };
    my $ec = keys %{ $entity_pkgs{$ent}||{} };
    my $pc = keys %{ $storepb_pkgs{$ent}||{} };
    print "$ent: " . (keys %u) . " (store=$ec storepb=$pc)\n";
    print "  - $_\n" for map { s{^/bench/repo/}{}; $_ } sort keys %u;
}
'

