use strict;
use warnings;

my @entities = qw(
    Attachment Memo MemoRelation InstanceSetting User UserSetting
    IdentityProvider Inbox Reaction MemoShare UserIdentity
);

# method name fragments
my %methods = (
    Attachment => [qw(CreateAttachment ListAttachments GetAttachment UpdateAttachment DeleteAttachment DeleteAttachments)],
    Memo => [qw(CreateMemo ListMemos GetMemo UpdateMemo DeleteMemo)],
    MemoRelation => [qw(UpsertMemoRelation ListMemoRelations GetMemoRelation DeleteMemoRelation)],
    InstanceSetting => [qw(UpsertInstanceSetting ListInstanceSettings GetInstanceSetting DeleteInstanceSetting)],
    User => [qw(CreateUser UpdateUser ListUsers GetUser DeleteUser GetCurrentUser)],
    UserSetting => [qw(UpsertUserSetting ListUserSettings GetUserSetting DeleteUserSettings)],
    IdentityProvider => [qw(CreateIdentityProvider ListIdentityProviders GetIdentityProvider UpdateIdentityProvider DeleteIdentityProvider)],
    Inbox => [qw(CreateInbox ListInboxes GetInbox UpdateInbox DeleteInbox)],
    Reaction => [qw(UpsertReaction ListReactions GetReaction DeleteReaction)],
    MemoShare => [qw(CreateMemoShare ListMemoShares GetMemoShare DeleteMemoShare)],
    UserIdentity => [qw(CreateUserIdentity ListUserIdentities GetUserIdentity DeleteUserIdentities)],
);

open my $lf, "<", "/tmp/go_files.txt" or die $!;
my @files = grep { $_ !~ m{/proto/} } <$lf>;
chomp @files;
close $lf;

print "Non-proto Go files outside store/: " . scalar(@files) . "\n\n";

my %type_pkgs; my %type_files;
my %rel_pkgs;
my %method_pkgs;
my %union_pkgs;
my %type_hits;

for my $path (@files) {
    open my $fh, "<", $path or die $path;
    my $text = do { local $/; <$fh> };
    close $fh;
    my $pkg = $path; $pkg =~ s{/[^/]+$}{};
    for my $ent (@entities) {
        if ($text =~ /\bstore\.\Q$ent\E\b/) {
            $type_pkgs{$ent}{$pkg} = 1;
            $type_files{$ent}{$path} = 1;
            $union_pkgs{$ent}{$pkg} = 1;
            my $n=0;
            for my $line (split /\n/, $text) {
                $n++;
                push @{$type_hits{$ent}}, sprintf("%s:%d:%s", $path, $n, $line) if $line =~ /\bstore\.\Q$ent\E\b/;
            }
        }
        for my $rel (("Find$ent","Update$ent","Delete$ent","Find${ent}Payload")) {
            if ($text =~ /\bstore\.\Q$rel\E\b/) {
                $rel_pkgs{$ent}{$pkg} = 1;
                $union_pkgs{$ent}{$pkg} = 1;
            }
        }
        for my $m (@{$methods{$ent}||[]}) {
            if ($text =~ /\b\Q$m\E\b/) {
                $method_pkgs{$ent}{$pkg} = 1;
                $union_pkgs{$ent}{$pkg} = 1;
            }
        }
    }
}

print "======= TYPE store.Entity =======\n";
for my $ent (sort { keys(%{$type_pkgs{$b}||{}}) <=> keys(%{$type_pkgs{$a}||{}}) || $a cmp $b } @entities) {
    printf "%s: %d pkgs, %d files\n", $ent, scalar(keys %{$type_pkgs{$ent}||{}}), scalar(keys %{$type_files{$ent}||{}});
    for my $p (sort keys %{$type_pkgs{$ent}||{}}) { $p =~ s{^/bench/repo/}{}; print "  $p\n"; }
}

print "\n======= TYPE + related query types =======\n";
for my $ent (sort {
    my %A=%{$type_pkgs{$a}||{}}; $A{$_}=1 for keys %{$rel_pkgs{$a}||{}};
    my %B=%{$type_pkgs{$b}||{}}; $B{$_}=1 for keys %{$rel_pkgs{$b}||{}};
    (keys %B)<=>(keys %A) || $a cmp $b
} @entities) {
    my %u = %{$type_pkgs{$ent}||{}}; $u{$_}=1 for keys %{$rel_pkgs{$ent}||{}};
    printf "%s: %d (type=%d rel=%d)\n", $ent, scalar(keys %u), scalar(keys %{$type_pkgs{$ent}||{}}), scalar(keys %{$rel_pkgs{$ent}||{}});
}

print "\n======= TYPE + related + methods =======\n";
for my $ent (sort { keys(%{$union_pkgs{$b}||{}}) <=> keys(%{$union_pkgs{$a}||{}}) || $a cmp $b } @entities) {
    printf "%s: %d (type=%d rel=%d method=%d)\n", $ent,
        scalar(keys %{$union_pkgs{$ent}||{}}),
        scalar(keys %{$type_pkgs{$ent}||{}}),
        scalar(keys %{$rel_pkgs{$ent}||{}}),
        scalar(keys %{$method_pkgs{$ent}||{}});
    my @extra = grep { !exists $type_pkgs{$ent}{$_} } keys %{$union_pkgs{$ent}||{}};
    if (@extra) {
        print "  extra: " . join(", ", map { s{^/bench/repo/}{}; $_ } sort @extra) . "\n";
    }
}

print "\n======= User type hits =======\n";
for my $h (@{$type_hits{User}||[]}) {
